def slugify(title):
    slug = title.lower()
    slug = slug.replace('&', ' and ')
    slug = ''.join(
        ch for ch in slug
        if ('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch == ' ' or ch == '-'
    )
    result = []
    in_separator = False
    for ch in slug:
        if ch == ' ' or ch == '-':
            if not in_separator:
                result.append('-')
                in_separator = True
        else:
            result.append(ch)
            in_separator = False
    slug = ''.join(result).strip('-')
    if len(slug) > 40:
        slug = slug[:40].rstrip('-')
    return slug
